package net.zartra.gui;
import org.bukkit.*;import org.bukkit.entity.Player;import org.bukkit.inventory.*;import java.io.*;import java.util.*;
final class GuiService{private final ZartraGUIPlugin plugin;private final MenuManager menus;GuiService(ZartraGUIPlugin p,MenuManager m){plugin=p;menus=m;}private ItemStack b(Material x,String n,String... lore){ItemStack s=new ItemStack(x);org.bukkit.inventory.meta.ItemMeta q=s.getItemMeta();q.setDisplayName(Chat.c(n));if(lore.length>0){List<String> l=new ArrayList<String>();for(String z:lore)l.add(Chat.c(z));q.setLore(l);}s.setItemMeta(q);return s;}void main(Player p){Inventory i=Bukkit.createInventory(new MenuManager.Holder("",false,MenuManager.Screen.MAIN),27,Chat.c("&bZartraGUI"));i.setItem(10,b(Material.CHEST,"&aExisting Menus"));i.setItem(11,b(Material.EMERALD,"&aCreate Menu"));i.setItem(16,b(Material.SLIME_BALL,"&aReload Plugin"));i.setItem(22,b(Material.BARRIER,"&cClose"));p.openInventory(i);}void list(Player p){Inventory i=Bukkit.createInventory(new MenuManager.Holder("",false,MenuManager.Screen.LIST),54,Chat.c("&bMenus"));int n=0;for(MenuDefinition d:menus.all())if(n<45)i.setItem(n++,b(Material.CHEST,"&e"+d.id,"&7Left edit, right preview"));i.setItem(49,b(Material.BOOK,"&7Back"));p.openInventory(i);}void edit(Player p,MenuDefinition d){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,true,MenuManager.Screen.NONE),d.rows*9,Chat.c("&cEditing: "+d.id));for(Map.Entry<Integer,MenuItem>x:d.items.entrySet())i.setItem(x.getKey(),x.getValue().stack());p.openInventory(i);p.sendMessage(Chat.c("&eRight-click an item to edit its persisted actions."));}void actionEditor(Player p,MenuDefinition d,int slot){if(!d.items.containsKey(slot))return;Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTIONS,slot),27,Chat.c("&bClick actions"));for(MenuClickType t:MenuClickType.values())i.setItem(t.ordinal(),b(Material.PAPER,"&e"+t.name(),"&7"+d.items.get(slot).actions(t).size()+" actions"));i.setItem(25,b(Material.ANVIL,"&eItem appearance"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void actionList(Player p,MenuDefinition d,int slot,MenuClickType t){List<ActionEntry>a=d.items.get(slot).actions(t);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_LIST,slot,t,-1),54,Chat.c("&b"+t.name()+" actions"));for(int n=0;n<a.size()&&n<45;n++){ActionEntry x=a.get(n);i.setItem(n,b(x.enabled?Material.PAPER:Material.REDSTONE,"&e"+(n+1)+". "+x.type,"&7"+x.value,"&7Delay: "+x.delay+" Chance: "+x.chance,"&7Enabled: "+x.enabled+" Stop: "+x.stopOnFailure));}i.setItem(45,b(Material.ARROW,"&7Back"));i.setItem(49,b(Material.EMERALD,"&aAdd action"));p.openInventory(i);}void actionEdit(Player p,MenuDefinition d,int slot,MenuClickType t,int n){ActionEntry a=d.items.get(slot).actions(t).get(n);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_EDIT,slot,t,n),27,Chat.c("&bEdit "+a.type));i.setItem(0,b(Material.PAPER,"&eEdit type/value","&7"+a.type+": "+a.value));i.setItem(1,b(a.enabled?Material.EMERALD:Material.REDSTONE,"&eToggle enabled","&7"+a.enabled));i.setItem(2,b(Material.BOOK,"&eDuplicate"));i.setItem(3,b(Material.ARROW,"&eMove up"));i.setItem(4,b(Material.ARROW,"&eMove down"));i.setItem(5,b(Material.WATCH,"&eDelay","&7"+a.delay+" ticks"));i.setItem(6,b(Material.GOLD_NUGGET,"&eChance","&7"+a.chance));i.setItem(7,b(Material.LEVER,"&eStop on failure","&7"+a.stopOnFailure));i.setItem(8,b(Material.SLIME_BALL,"&aTest"));i.setItem(9,b(Material.BARRIER,"&cDelete"));i.setItem(10,b(Material.NETHER_STAR,"&eConditions","&7"+a.conditions.size()+" configured"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void itemSettings(Player p,MenuDefinition d,int slot){MenuItem x=d.items.get(slot);if(x==null)return;Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ITEM_SETTINGS,slot),27,Chat.c("&bItem settings"));i.setItem(0,b(Material.CHEST,"&eMaterial","&7"+x.material));i.setItem(1,b(Material.PAPER,"&eDisplay name","&7"+(x.name==null?"":x.name)));i.setItem(2,b(Material.BOOK,"&eLore","&7"+x.lore.size()+" lines"));i.setItem(3,b(Material.GOLD_INGOT,"&eAmount","&7"+x.amount));i.setItem(4,b(Material.INK_SACK,"&eLegacy data","&7"+x.data));i.setItem(5,b(Material.GLOWSTONE_DUST,"&eGlow","&7"+x.glow));i.setItem(6,b(Material.WATCH,"&eCooldown","&7"+x.cooldown));i.setItem(7,b(Material.NETHER_STAR,"&ePriority","&7"+x.priority));i.setItem(8,b(Material.PAPER,"&eFallback material","&7"+x.fallbackMaterial));i.setItem(9,b(Material.DIAMOND,"&eUnbreakable","&7"+x.unbreakable));i.setItem(10,b(Material.NAME_TAG,"&eCustom model data","&7"+x.customModelData));i.setItem(11,b(Material.SKULL_ITEM,"&eHead owner","&7"+x.headOwner));i.setItem(12,b(Material.LEATHER_CHESTPLATE,"&eLeather color","&7"+x.leatherColor));i.setItem(13,b(Material.ENCHANTED_BOOK,"&eEnchantments","&7"+x.enchantments));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void editItemValue(final Player p,final MenuDefinition d,final int slot,final int control){ask(p,"&eEnter item value",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuItem x=d.items.get(slot);try{if(control==0){Material m=CompatMaterial.find(raw);if(m==Material.STONE&&!"STONE".equalsIgnoreCase(raw))throw new IllegalArgumentException();x.material=raw.toUpperCase();}else if(control==1)x.name=raw;else if(control==3)x.amount=Math.max(1,Math.min(64,Integer.parseInt(raw)));else if(control==4)x.data=Integer.parseInt(raw);else if(control==6)x.cooldown=Math.max(0,Long.parseLong(raw));else if(control==7)x.priority=Integer.parseInt(raw);else if(control==8)x.fallbackMaterial=raw;else if(control==9)x.unbreakable=!x.unbreakable;else if(control==10)x.customModelData=Integer.parseInt(raw);else if(control==11)x.headOwner=raw;else if(control==12){if(!raw.matches("[0-9]{1,3},[0-9]{1,3},[0-9]{1,3}"))throw new IllegalArgumentException();x.leatherColor=raw;}else if(control==13){String[] ep=raw.split(":",2);org.bukkit.enchantments.Enchantment en=org.bukkit.enchantments.Enchantment.getByName(ep[0].toUpperCase());if(en==null)throw new IllegalArgumentException();x.enchantments.put(en.getName(),Integer.parseInt(ep[1]));}else if(control==5)x.glow=!x.glow;save(q,d);itemSettings(q,d,slot);}catch(Exception e){q.sendMessage(Chat.c("&cInvalid item value."));itemSettings(q,d,slot);}}});}void loreEditor(Player p,MenuDefinition d,int slot){MenuItem x=d.items.get(slot);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.LORE_EDITOR,slot),54,Chat.c("&bLore editor"));for(int n=0;n<x.lore.size()&&n<45;n++)i.setItem(n,b(Material.PAPER,"&e"+(n+1),"&7"+x.lore.get(n)));i.setItem(45,b(Material.ARROW,"&7Back"));i.setItem(49,b(Material.EMERALD,"&aAdd line"));p.openInventory(i);}void addLore(final Player p,final MenuDefinition d,final int slot){ask(p,"&eEnter lore line",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuItem x=d.items.get(slot);if(x.lore.size()>=100){q.sendMessage(Chat.c("&cLore limit reached."));}else{x.lore.add(raw);save(q,d);}loreEditor(q,d,slot);}});}void menuSettings(Player p,MenuDefinition d){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.MENU_SETTINGS),27,Chat.c("&bMenu settings"));i.setItem(0,b(Material.PAPER,"&eTitle","&7"+d.title));i.setItem(1,b(Material.CHEST,"&eRows","&7"+d.rows));i.setItem(2,b(Material.IRON_INGOT,"&eOpening permission","&7"+d.openingPermission));i.setItem(3,b(Material.NOTE_BLOCK,"&eOpening sound","&7"+d.openingSound));i.setItem(4,b(Material.NOTE_BLOCK,"&eClosing sound","&7"+d.closingSound));i.setItem(5,b(Material.STAINED_GLASS_PANE,"&eDefault filler","&7"+d.defaultFillerMaterial));i.setItem(6,b(Material.EYE_OF_ENDER,"&eMaximum viewers","&7"+d.maximumViewers));i.setItem(7,b(Material.BOOK,"&ePagination slots","&7"+d.paginationContentSlots));i.setItem(8,b(Material.WATCH,"&eRefresh interval","&7"+d.refreshInterval+" ticks"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void editMenuText(final Player p,final MenuDefinition d,final int control){ask(p,"&eEnter new value",new ChatInputManager.Callback(){public void run(Player q,String raw){try{if(control==0)d.title=raw;else if(control==1)d.rows=MenuDefinition.validRows(Integer.parseInt(raw));else if(control==2)d.openingPermission=raw;else if(control==3)d.openingSound=raw;else if(control==4)d.closingSound=raw;else if(control==5){if(raw.length()>0&&CompatMaterial.find(raw)==Material.STONE&&!"STONE".equalsIgnoreCase(raw))throw new IllegalArgumentException();d.defaultFillerMaterial=raw;}else if(control==6)d.maximumViewers=Math.max(0,Math.min(100,Integer.parseInt(raw)));else if(control==7){d.paginationContentSlots.clear();if(raw.trim().length()>0)for(String x:raw.split(","))d.paginationContentSlots.add(Integer.parseInt(x.trim()));if(!d.validPaginationSlots())throw new IllegalArgumentException();}else if(control==8)d.refreshInterval=Math.max(0,Long.parseLong(raw));save(q,d);menuSettings(q,d);}catch(Exception e){q.sendMessage(Chat.c("&cInvalid setting value."));menuSettings(q,d);}}});}void conditionList(Player p,MenuDefinition d,int slot,MenuClickType t,int action){ActionEntry a=d.items.get(slot).actions(t).get(action);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_LIST,slot,t,action),54,Chat.c("&bConditions"));for(int n=0;n<a.conditions.size()&&n<45;n++){ConditionEntry c=a.conditions.get(n);i.setItem(n,b(c.enabled?Material.PAPER:Material.REDSTONE,"&e"+(n+1)+". "+c.type.name(),"&7"+c.value,"&7Enabled: "+c.enabled+" Inverted: "+c.inverted));}i.setItem(45,b(Material.ARROW,"&7Back"));i.setItem(48,b(Material.LEVER,"&eMode: "+a.conditionMode));i.setItem(49,b(Material.EMERALD,"&aAdd condition"));p.openInventory(i);}void conditionTypes(Player p,MenuDefinition d,int slot,MenuClickType t,int action){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_TYPES,slot,t,action),27,Chat.c("&bCondition type"));int n=0;for(ConditionEntry.Type type:ConditionEntry.Type.values())if(n<26)i.setItem(n++,b(Material.PAPER,"&e"+type.name(),"&7Click to add"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void conditionEdit(Player p,MenuDefinition d,int slot,MenuClickType t,int action,int sub){ConditionEntry c=d.items.get(slot).actions(t).get(action).conditions.get(sub);Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.CONDITION_EDIT,slot,t,action,sub),27,Chat.c("&bEdit condition"));i.setItem(0,b(Material.PAPER,"&eEdit value","&7"+c.value));i.setItem(1,b(c.enabled?Material.EMERALD:Material.REDSTONE,"&eToggle enabled","&7"+c.enabled));i.setItem(2,b(Material.LEVER,"&eToggle inversion","&7"+c.inverted));i.setItem(3,b(Material.BOOK,"&eDuplicate"));i.setItem(4,b(Material.ARROW,"&eMove up"));i.setItem(5,b(Material.ARROW,"&eMove down"));i.setItem(6,b(Material.SLIME_BALL,"&aTest"));i.setItem(9,b(Material.BARRIER,"&cDelete"));i.setItem(26,b(Material.ARROW,"&7Back"));p.openInventory(i);}void addCondition(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int action,final ConditionEntry.Type type){final ActionEntry a=d.items.get(slot).actions(t).get(action);final ConditionEntry c=new ConditionEntry(type,"");c.order=a.conditions.size();a.conditions.add(c);if(!new ConditionRegistry().get(type).valueRequired){save(p,d);conditionEdit(p,d,slot,t,action,a.conditions.size()-1);return;}ask(p,"&eEnter value for "+type.name(),new ChatInputManager.Callback(){public void run(Player q,String raw){c.value=raw;if(!new ConditionRegistry().valid(c)){a.conditions.remove(c);q.sendMessage(Chat.c("&cInvalid condition value."));conditionTypes(q,d,slot,t,action);return;}save(q,d);conditionEdit(q,d,slot,t,action,a.conditions.size()-1);}});}void editConditionValue(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int action,final int sub){ask(p,"&eEnter condition value",new ChatInputManager.Callback(){public void run(Player q,String raw){ConditionEntry c=d.items.get(slot).actions(t).get(action).conditions.get(sub);String old=c.value;c.value=raw;if(!new ConditionRegistry().valid(c)){c.value=old;q.sendMessage(Chat.c("&cInvalid condition value."));}else save(q,d);conditionEdit(q,d,slot,t,action,sub);}});}void deleteConfirm(Player p,MenuDefinition d,int slot,MenuClickType t,int n){Inventory i=Bukkit.createInventory(new MenuManager.Holder(d.id,false,MenuManager.Screen.ACTION_DELETE,slot,t,n),9,Chat.c("&cDelete action?"));i.setItem(3,b(Material.EMERALD,"&aConfirm delete"));i.setItem(5,b(Material.REDSTONE,"&cCancel"));p.openInventory(i);}void add(final Player p,final MenuDefinition d,final int slot,final MenuClickType t){ask(p,"&eEnter TYPE: value",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuAction z=MenuAction.parse(raw);if(z==null||plugin.actions().registry().get(z.type.name())==null){q.sendMessage(Chat.c("&cUnknown action type."));return;}ActionEntry a=new ActionEntry();a.type=z.type.name();a.value=z.value;a.order=d.items.get(slot).actions(t).size();d.items.get(slot).actions(t).add(a);save(q,d);actionList(q,d,slot,t);}});}void editValue(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int n){ask(p,"&eEnter TYPE: value",new ChatInputManager.Callback(){public void run(Player q,String raw){MenuAction z=MenuAction.parse(raw);if(z==null||plugin.actions().registry().get(z.type.name())==null){q.sendMessage(Chat.c("&cUnknown action type."));return;}ActionEntry a=d.items.get(slot).actions(t).get(n);a.type=z.type.name();a.value=z.value;save(q,d);actionEdit(q,d,slot,t,n);}});}void number(final Player p,final MenuDefinition d,final int slot,final MenuClickType t,final int n,final boolean chance){ask(p,"&eEnter "+(chance?"chance 0-100":"delay ticks 0-72000"),new ChatInputManager.Callback(){public void run(Player q,String raw){try{ActionEntry a=d.items.get(slot).actions(t).get(n);if(chance){double x=Double.parseDouble(raw);if(!ActionValidator.chance(x))throw new NumberFormatException();a.chance=x;}else{long x=Long.parseLong(raw);if(!ActionValidator.delay(x))throw new NumberFormatException();a.delay=x;}save(q,d);actionEdit(q,d,slot,t,n);}catch(NumberFormatException e){q.sendMessage(Chat.c("&cInvalid number."));}}});}private void ask(Player p,String prompt,ChatInputManager.Callback c){plugin.inputs().begin(p,c);p.closeInventory();p.sendMessage(Chat.c(prompt+" &7(type cancel to abort)"));}void save(Player p,MenuDefinition d){try{menus.save(d);}catch(IOException e){plugin.getLogger().warning("Unable to save "+d.id+": "+e.getMessage());p.sendMessage(Chat.c("&cSave failed; see console."));}}void saveEditor(Inventory inv){if(!(inv.getHolder() instanceof MenuManager.Holder))return;MenuManager.Holder h=(MenuManager.Holder)inv.getHolder();if(!h.edit)return;MenuDefinition d=menus.get(h.id);if(d==null)return;Map<Integer,MenuItem>old=new HashMap<Integer,MenuItem>(d.items);d.items.clear();for(int slot=0;slot<inv.getSize();slot++){ItemStack s=inv.getItem(slot);if(s!=null&&s.getType()!=Material.AIR){MenuItem prior=old.get(slot),x=new MenuItem(s,null);if(prior!=null)x.copyRuntimeFrom(prior);d.items.put(slot,x);}}try{menus.save(d);}catch(IOException e){plugin.getLogger().warning("Unable to save "+d.id+": "+e.getMessage());}}
}